async function updateApi(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'更新服务暂时不可用');return data;}
function paintUpdateNotice(){const notice=$('#update-notice');if(!notice||!updateState)return;notice.hidden=!updateState.notify||!['available','ready'].includes(updateState.status);if(!notice.hidden)notice.innerHTML=`<span><i class="ph ph-download-simple" aria-hidden="true"></i><strong>灵思剪辑有新版本 v${esc(updateState.latest_version)}</strong><small>${updateState.status==='ready'?'更新包已下载并通过校验':'查看本次更新并下载到本机'}</small></span><div class="actions"><button data-action="update-open">查看更新</button><button class="text-button" data-action="update-later">稍后提醒</button><button class="text-button" data-action="update-ignore">忽略此版本</button></div>`;}
function updatePanel(){const u=updateState||{status:'checking',message:'正在读取更新状态…'},downloading=u.status==='downloading',ready=u.status==='ready',available=u.status==='available';return `<div class="update-dialog"><div class="update-version-line"><span>当前版本 <b>v${esc(u.current_version||'0.4.0')}</b></span>${u.latest_version?`<i class="ph ph-arrow-right" aria-hidden="true"></i><span>最新版本 <strong>v${esc(u.latest_version)}</strong></span>`:''}</div><p role="status">${esc(u.message||'正在检查更新…')}</p>${downloading?`<progress max="${u.total||1}" value="${u.received||0}"></progress><small>已下载 ${((u.received||0)/1048576).toFixed(1)} / ${((u.total||0)/1048576).toFixed(1)} MB</small>`:''}${u.notes?`<details class="update-notes" open><summary>本次更新内容</summary><p>${esc(u.notes)}</p></details>`:''}<div class="actions update-actions"><button data-action="update-check" ${u.busy?'disabled':''}>重新检查</button>${available&&u.download_ready?'<button class="primary" data-action="update-download">下载更新</button>':''}${ready?'<button class="primary" data-action="update-confirm">更新并重启</button>':''}${u.releases_url?`<a class="button" href="${esc(u.releases_url)}" target="_blank" rel="noopener noreferrer">查看 GitHub 发布页 ↗</a>`:''}</div><p class="muted">每天自动检查一次。断网不影响本地剪辑；安装前校验并备份程序文件，浏览器中的视频工程不会上传。</p></div>`;}
