async function pollUpdates(){if(updatePolling||document.hidden)return;updatePolling=true;try{updateState=await updateApi('/api/updates');paintUpdateNotice();paintUpdateDialog();if(updateState.busy||updateState.status==='downloading'){clearTimeout(updateTimer);updateTimer=setTimeout(pollUpdates,700);}}catch{}finally{updatePolling=false;}}
