  if(spec?.series)body+=`<label>趋势数据（8 个数值，以逗号分隔）<input data-series value="${esc((c.series||[]).join(', '))}"></label>`;
  if(spec?.count)body+=`<label class="check-field"><input type="checkbox" data-count ${c.count?'checked':''}>数字递增入场</label>`;
  if(spec?.images)body+=`<div class="section-label">${spec.requiredImages?'上传 3 张图片后可导出':'可选图片'}</div><div class="image-slots">${Array.from({length:spec.images},(_,i)=>`<div><button data-action="upload-image" data-slot="${i}">${c.images?.[i]?`<img src="${c.images[i]}" alt="图片 ${i+1}">`:`＋ 图片 ${i+1}`}</button>${c.images?.[i]?`<button class="text-button" data-action="remove-image" data-slot="${i}">移除</button>`:''}</div>`).join('')}</div>`;
  body+=`<div class="field-pair"><label>开始 / 秒<input data-field="start" type="number" min="0" max="${p.duration}" step="0.1" value="${c.start.toFixed(2)}"></label><label>结束 / 秒<input data-field="end" type="number" min="0" max="${p.duration}" step="0.1" value="${c.end.toFixed(2)}"></label></div>`;
  if(c.type==='chapter-progress')body+=`<div class="actions"><button data-action="add-chapter" ${parts.length>=12?'disabled':''}>＋ 添加章节</button></div><label class="color-field">强调色<input data-field="color" type="color" value="${c.color}"></label><label class="color-field">文字色<input data-field="textColor" type="color" value="${c.textColor||'#f7fbff'}"></label><div class="section-label">章节起点 / 秒</div>${parts.map((v,i)=>`<label>${esc(v)} <button class="chapter-remove" data-action="remove-chapter" data-index="${i}" ${parts.length<=2?'disabled':''} aria-label="删除章节 ${i+1}">×</button><input data-chapter="${i}" type="number" step="0.1" ${!i?'disabled':''} value="${(c.start+(c.chapterTimes?.[i]??i/parts.length)*(c.end-c.start)).toFixed(2)}"></label>`).join('')}`;
