async function setAudioFile(candidate){
 bgm.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl='';audioFile=candidate||null;
 if(!candidate){bgm.removeAttribute('src');bgm.load();return;}
 if(candidate.size>250*1024*1024||!(/audio\/(mpeg|wav|x-wav|mp4|aac)/.test(candidate.type)||/\.(mp3|wav|m4a)$/i.test(candidate.name)))throw Error('请选择 250 MB 以内的 MP3、WAV 或 M4A 音乐');
 audioUrl=URL.createObjectURL(candidate);bgm.src=audioUrl;bgm.load();await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('音乐读取超时，请更换文件')),10000);bgm.onloadedmetadata=()=>{clearTimeout(timer);resolve();};bgm.onerror=()=>{clearTimeout(timer);reject(Error('音乐文件无法读取'));};});
}
function seekTimeline(value){playhead=Math.min(Math.max(0,Number(value)||0),Math.max(0,p.duration-.001));const hit=mapTimelineTime(p,playhead);if(hit&&Math.abs(video.currentTime-hit.sourceTime)>.03)video.currentTime=hit.sourceTime;syncPlayback();}
function musicVolumeAt(time){const a=p.audio;if(!a||time<a.start||time>=a.end)return 0;let volume=a.volume;if(a.fadeIn&&time<a.start+a.fadeIn)volume*=Math.max(0,(time-a.start)/a.fadeIn);if(a.fadeOut&&time>a.end-a.fadeOut)volume*=Math.max(0,(a.end-time)/a.fadeOut);return volume;}
