 'split-video':()=>{if(!file)return;modify(()=>{const next=splitClip(p,playhead);if(!next)throw Error('请把播放头放在片段中间再分割');selected=next;});},
 'delete-video-clip':()=>{const c=current();if(!p.videoClips.includes(c))return toast('请先选中一个视频片段');if(p.videoClips.length<=1)return toast('至少保留一个视频片段');modify(()=>{deleteClip(p,c.id);selected=null;playhead=Math.min(playhead,p.duration);});},
