 'demo':async()=>{const r=await fetch('/demo-presenter-v2.mp4');if(!r.ok)throw Error('演示素材未加载，请重试');const candidate=new File([await r.blob()],'灵思人物演示.mp4',{type:'video/mp4'});if(!await importVideo(candidate,demoProject()))return;dirty=true;$('#save-status').innerHTML='<i class="unsaved"></i>演示副本 · 可自由编辑';video.play().catch(()=>toast('点击播放，开始体验'));toast('试着改一句标题，再调整一个动效，最后导出看看');},
