 'remove-chapter':b=>modify(()=>{Object.assign(current(),removeChapter(current(),+b.dataset.index));}),
 'filter':b=>{libraryGroup=b.dataset.group;renderLibrary();},
 'import-backup':()=>$('#backup-file').click(),
 'backup':()=>{if(file)download(packProject(validateProject(p),file,audioFile),`${p.name}.linsi`);},
 'upload-image':b=>{imageSlot=+b.dataset.slot;$('#image-file').click();},
 'remove-image':b=>modify(()=>{current().images[+b.dataset.slot]='';}),
 'apply-accent':()=>{const color=$('#global-color').value;modify(()=>{p.accent=color;p.motions.forEach(m=>m.color=color);});},
 'duplicate':()=>{const c=current();if(!c)return;const list=p.layers.includes(c)?p.layers:c.type?p.motions:p.captions;if(list.length>=(c.type?200:2000))return toast('片段数量已达上限');modify(()=>{const copy=structuredClone(c);copy.id=id();const shift=Math.min(.3,p.duration-c.end);copy.start+=shift;copy.end+=shift;list.push(copy);selected=copy.id;});},
 'play':()=>{selectionPreview=null;timelinePlaying=!timelinePlaying;lastPlayback=performance.now();if(timelinePlaying&&playhead>=p.duration-.02)playhead=0;syncPlayback();},'rewind':()=>{timelinePlaying=false;seekTimeline(0);},'mute':()=>{previewMuted=!previewMuted;syncPlayback();$('#mute').textContent=`原声 ${previewMuted?'关':'开'}`;toast(previewMuted?'预览原声已静音':'已恢复预览原声');},
 'view':b=>{original=b.dataset.value==='original';document.querySelectorAll('[data-action="view"]').forEach(x=>x.classList.toggle('active',x===b));},
 'add-motion':b=>{if(!file)return toast('先导入视频，再添加动效');if(p.motions.length>=200)return toast('当前工程动效数量已达上限');modify(()=>{const c=motion(b.dataset.type,playhead,p.duration);p.motions.push(c);selected=c.id;});},
 'add-caption':()=>{if(!file)return;if(p.captions.length>=2000)return toast('当前工程字幕数量已达上限');modify(()=>{const start=Math.min(playhead,Math.max(0,p.duration-.1)),c={id:id(),text:'输入你的字幕',start,end:Math.min(p.duration,start+3)};p.captions.push(c);selected=c.id;tab='captions';});},
 'select':b=>{selectionPreview=null;selected=b.dataset.id==='bgm-track'?null:b.dataset.id;const c=current();if(c){const row=p.videoClips.includes(c)?layoutClips(p).find(x=>x.id===c.id):c;seekTimeline(row.timelineStart??row.start);}renderInspector();renderTracks();},
 'theme':b=>{if(!file)return toast('先导入视频，再设置字幕');modify(()=>{p.subtitle.theme=b.dataset.theme;});},
 'position':b=>modify(()=>{const c=current();if(c){c.x=+b.dataset.x;c.y=+b.dataset.y;}}),
 'remove':()=>modify(()=>{p.captions=p.captions.filter(c=>c.id!==selected);p.motions=p.motions.filter(c=>c.id!==selected);p.layers=p.layers.filter(c=>c.id!==selected);selected=null;}),
 'preview-selected':()=>{const c=current();if(c&&!p.videoClips.includes(c)){selectionPreview={id:c.id,end:c.end};original=false;seekTimeline(c.start);timelinePlaying=true;lastPlayback=performance.now();syncPlayback();}},
 'undo':()=>{if(!undo.length)return;redo.push(structuredClone(p));p=undo.pop();selected=null;changed();},'redo':()=>{if(!redo.length)return;undo.push(structuredClone(p));p=redo.pop();selected=null;changed();},
 'save':async()=>{if(!file)return;await storage.save(validateProject(p),file,audioFile);dirty=false;$('#save-status').innerHTML='<i></i>已保存到当前浏览器';toast('视频、音乐与编辑内容已保存');},
 'open-projects':async()=>{const rows=await storage.list();dialog('打开本地工程',`<p class="muted">工程保存在当前浏览器，选择后继续编辑。</p><button data-action="import-backup">从工程包恢复</button><div class="project-list">${rows.length?rows.map(r=>`<button data-action="load" data-id="${r.id}"><b>${esc(r.name)}</b><span>${time(r.duration)} · ${new Date(r.updated).toLocaleString()}</span></button>`).join(''):'<div class="empty-list">还没有保存的工程，先导入一条视频吧。</div>'}</div>`);},
 'load':async b=>{const row=await storage.load(b.dataset.id);if(!row?.file)throw Error('本地视频不可用，请重新导入原视频');await importVideo(row.file,row.project);await setAudioFile(row.audioFile||null);$('#dialog').close();},
 'caption-replace':()=>{const find=$('#caption-find').value,replacement=$('#caption-replace').value;if(!find)return toast('请先填写要查找的文字');modify(()=>replaceCaptionText(p.captions,find,replacement));},
